-- Dynamic flag 0x800 is not a 5.4.8 flag (LoA: 0) on three Northshire mobs
UPDATE `creature_template` SET `dynamicflags` = 0 WHERE `entry` IN (49871,49874,50039) AND `dynamicflags` = 2048;

-- Difficulty templates follow their normal mode (the core reports a differing npcflag at load)
UPDATE `creature_template` d JOIN `creature_template` b ON b.`difficulty_entry_1` = d.`entry` SET d.`npcflag` = d.`npcflag` & ~2
  WHERE d.`npcflag` & 2 AND NOT (b.`npcflag` & 2) AND NOT EXISTS (SELECT 1 FROM `creature_queststarter` q WHERE q.`id` = d.`entry`) AND NOT EXISTS (SELECT 1 FROM `creature_questender` q WHERE q.`id` = d.`entry`);
UPDATE `creature_template` d JOIN `creature_template` b ON b.`difficulty_entry_2` = d.`entry` SET d.`npcflag` = d.`npcflag` & ~2
  WHERE d.`npcflag` & 2 AND NOT (b.`npcflag` & 2) AND NOT EXISTS (SELECT 1 FROM `creature_queststarter` q WHERE q.`id` = d.`entry`) AND NOT EXISTS (SELECT 1 FROM `creature_questender` q WHERE q.`id` = d.`entry`);
UPDATE `creature_template` d JOIN `creature_template` b ON b.`difficulty_entry_3` = d.`entry` SET d.`npcflag` = d.`npcflag` & ~2
  WHERE d.`npcflag` & 2 AND NOT (b.`npcflag` & 2) AND NOT EXISTS (SELECT 1 FROM `creature_queststarter` q WHERE q.`id` = d.`entry`) AND NOT EXISTS (SELECT 1 FROM `creature_questender` q WHERE q.`id` = d.`entry`);
